export function Onboarding({
  heading = "{{heading}}",
  subheading = "{{subheading}}",
  stage = "{{stage}}",
  accent = "{{accent}}",
  showSkip = {{showSkip}},
}) {
  const steps = [["profile", "Set up profile"], ["team", "Invite your team"], ["done", "Start exploring"]];
  return (
    <section aria-label={heading} style={{ fontFamily: "system-ui, sans-serif", fontSize: 13.5, color: "#241430", background: "#FAF7F2", maxWidth: 340, width: 340, padding: 20, borderRadius: 14, boxSizing: "border-box" }}>
      <h2 style={{ margin: "0 0 6px", fontSize: 18, fontWeight: 700 }}>{heading}</h2>
      <p style={{ margin: "0 0 14px", color: "#241430b3" }}>{subheading}</p>
      <ol style={{ listStyle: "none", margin: "0 0 16px", padding: 0, display: "flex", flexDirection: "column", gap: 6 }}>
        {steps.map(([id, label]) => (
          <li key={id} style={{ padding: "8px 10px", borderRadius: 8, background: stage === id ? accent : "#fff", fontWeight: stage === id ? 700 : 400 }}>{label}</li>
        ))}
      </ol>
      <div style={{ display: "flex", gap: 10, alignItems: "center" }}>
        <button type="button" style={{ background: "#241430", color: "#FAF7F2", border: "none", borderRadius: 8, padding: "9px 18px", font: "inherit", fontWeight: 700, cursor: "pointer" }}>Continue</button>
        {showSkip && <button type="button" style={{ background: "transparent", border: "none", color: "#241430a0", font: "inherit", textDecoration: "underline", cursor: "pointer" }}>Skip for now</button>}
      </div>
    </section>
  );
}
